namespace ShopArticles.Core.Contracts;

// Payload for creating a new article. The rules are in CreateArticleRequestValidator.
public class CreateArticleRequest
{
    // Must NOT be sent; the id is generated by the server. Kept on the contract
    // only so that a client-supplied id can be rejected with 400.
    public long? ArticleId { get; set; }
    public string? Name { get; set; }
    public string? Description { get; set; }
    public string? Category { get; set; }
    public decimal? Price { get; set; }
    public string? Currency { get; set; }
}
